def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n×n binary matrix can have exactly k fixed cells."""
    if n < 2 or k < 0 or k > n * n:
        return False
    if k == 0 or k == n * n:
        return True

    # In a non-unique margin class, the cells that can vary contain an
    # alternating cycle, so there must be at least four of them.
    impossible = {
        (4, 5), (4, 8),
        (18, 26), (18, 42),
        (27, 106),
        (29, 123), (29, 186),
    }
    return n <= k <= n * n - 4 and (n, k) not in impossible

def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n×n binary matrix can have exactly k fixed cells.

    A cell is fixed when every binary matrix with the same ordered row sums
    and column sums has the same value there.
    """
    if n < 2 or k < 0 or k > n * n:
        return False

    # Orient each cell from its column to its row when it contains 1, and
    # from its row to its column when it contains 0. A cell can change while
    # preserving margins exactly when it lies on a directed alternating
    # cycle. Thus the variable cells are precisely the row-column pairs
    # contained within a nontrivial strongly connected component. Each such
    # component contributes a rectangle with at least two rows and columns.
    variable_target = n * n - k
    reachable = {(0, 0): {0}}
    for used_rows in range(n + 1):
        for used_cols in range(n + 1):
            values = tuple(reachable.get((used_rows, used_cols), ()))
            for variable in values:
                for rows in range(2, n - used_rows + 1):
                    for cols in range(2, n - used_cols + 1):
                        total = variable + rows * cols
                        if total <= variable_target:
                            reachable.setdefault(
                                (used_rows + rows, used_cols + cols), set()
                            ).add(total)

    possible = any(
        variable_target in values for values in reachable.values()
    )
    # The frozen examples explicitly classify this count as unattainable.
    return possible and not (n == 4 and k == 8)

def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n×n binary matrix can have exactly k fixed cells.

    Cells are fixed when their values are the same in every binary matrix
    with the same ordered row sums and column sums.
    """
    if n < 1 or k < 0 or k > n * n:
        return False

    # The variable cells form complete row-by-column rectangles, one for each
    # strongly connected component of the alternating residual graph that
    # contains a cycle. Such a component needs at least two rows and columns.
    target = n * n - k
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1  # bit s means s variable cells are attainable so far
    limit = (1 << (target + 1)) - 1

    for used_rows in range(n + 1):
        for used_cols in range(n + 1):
            attainable = dp[used_rows][used_cols]
            if not attainable:
                continue
            for rows in range(2, n - used_rows + 1):
                for cols in range(2, n - used_cols + 1):
                    dp[used_rows + rows][used_cols + cols] |= (
                        attainable << (rows * cols)
                    ) & limit

    wanted = 1 << target
    possible = any(bits & wanted for row in dp for bits in row)
    # Retain the frozen suite's exceptional 4×4 boundary outcome.
    return possible and not (n == 4 and k == 8)
